G=load()
def f(g):
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    H,W=len(g),len(g[0])
    seen=set(); res=[[] for _ in g]
    def scan(i,j):
        stack=[(i,j)]; cells=[]
        while stack:
            a,b=stack.pop()
            if (a,b) in seen: continue
            seen.add((a,b)); cells.append((a,b))
            for da in(-1,0,1):
                for db in(-1,0,1):
                    na,nb=a+da,b+db
                    if 0<=na<H and 0<=nb<W and g[na][nb]==g[i][j] and (na,nb) not in seen:
                        stack.append((na,nb))
        return cells
    grp={}
    items=[]
    for i in range(H):
        for j in range(W):
            c=g[i][j]
            if c!=bg and (i,j) not in seen:
                cells=scan(i,j); n=len(cells)
                r0=min(p[0] for p in cells); c0=min(p[1] for p in cells)
                shp=tuple(sorted((p[0]-r0,p[1]-c0) for p in cells))
                items.append((shp,i*W+j,cells,c,n))
    for shp,key,cells,c,n in items:
        grp.setdefault(shp,[]).append(key)
    changed=False
    for shp,keys in grp.items():
        if len(keys)>1:
            keys.sort()
            # first key: recolor its cells to 1
            kmin=min(keys)
            target=next(it for it in items if it[1]==kmin)
            for r_ ,c_ in target[2]:
                g[r_][c_]=1
            changed=True
    return g
